// And groups predicates with the AND operator between them.
func And(predicates ...predicate.TaskPlan) predicate.TaskPlan {
	return predicate.TaskPlan(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.TaskPlan) predicate.TaskPlan {
	return predicate.TaskPlan(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.TaskPlan) predicate.TaskPlan {
	return predicate.TaskPlan(sql.NotPredicates(p))
}
